ValidationRule.errorConditionFormula:
AND(
    /* Bypass validation for authorized rollback users */
    NOT($Permission.Zeta_Rollback_Lottery),

    TEXT(PRIORVALUE(Status)) = "Seat Accepted",

    /* Only validate when Status actually changes */
    TEXT(Status) <> TEXT(PRIORVALUE(Status)),

    /* Always allow Withdrawn/Declined */
    NOT(ISPICKVAL(Status, "Withdrawn/Declined"))
)
